import React, { useEffect, useState } from "react";
import { createEmployee, updateEmployee } from "../api";

function EmployeeForm({ onSuccess, editing, setEditing }) {
  const [form, setForm] = useState({ name: "", department: "", salary: "" });

  useEffect(() => {
    if (editing) setForm(editing);
  }, [editing]);

  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (form.id) {
      await updateEmployee(form.id, form);
    } else {
      await createEmployee(form);
    }

    setForm({ name: "", department: "", salary: "" });
    setEditing(null);
    onSuccess();
  };

  return (
    <form onSubmit={handleSubmit}>
      <h3>{form.id ? "Update Employee" : "Add Employee"}</h3>

      <input name="name" placeholder="Name" value={form.name} onChange={handleChange} />
      <input name="department" placeholder="Department" value={form.department} onChange={handleChange} />
      <input name="salary" placeholder="Salary" value={form.salary} onChange={handleChange} />

      <button type="submit">Save</button>
      {form.id && <button onClick={() => { setEditing(null); setForm({ name:"", department:"", salary:"" }); }}>Cancel</button>}
    </form>
  );
}

export default EmployeeForm;
